export function createFilter(host) {
  const palettes = [
    ['#ffbd59', '#ffe47a', '#ff8a72'],
    ['#8be3c1', '#b6f0df', '#70c9a8'],
    ['#f6a6c8', '#ffc6a1', '#cfb1f2']
  ];
  let paletteIndex = 0;

  host.onTap(() => {
    paletteIndex = (paletteIndex + 1) % palettes.length;
  });

  host.onFrame(({ ctx, width, height, faces, time }) => {
    const face = faces?.[0];
    const p = face?.landmarks;
    if (!p?.nose || !p.leftEye || !p.rightEye) return;

    const eyeSpan = Math.hypot(
      (p.rightEye.x - p.leftEye.x) * width,
      (p.rightEye.y - p.leftEye.y) * height
    );
    if (eyeSpan < 1) return;

    const cx = p.nose.x * width;
    const cy = p.nose.y * height;
    const colors = palettes[paletteIndex];

    ctx.save();
    for (let i = 0; i < 6; i++) {
      const angle = time * 0.48 + i * (Math.PI * 2 / 6);
      const x = cx + Math.cos(angle) * eyeSpan * 1.02;
      const y = cy + Math.sin(angle) * eyeSpan * 0.78 - eyeSpan * 0.08;
      const radius = eyeSpan * (0.105 + (i % 3) * 0.018);

      ctx.beginPath();
      ctx.arc(x, y, radius, 0, Math.PI * 2);
      ctx.fillStyle = colors[i % colors.length];
      ctx.globalAlpha = 0.78;
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.lineWidth = Math.max(1, eyeSpan * 0.025);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(x - radius * 0.3, y - radius * 0.34, radius * 0.19, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
      ctx.fill();
    }
    ctx.restore();
  });
}
